{"implementation": "def solve(case):
    word_token_indices = case['word_token_indices']
    word_labels = case['word_labels']
    token_count = case['token_count']

    if len(word_token_indices) != len(word_labels):
        raise ValueError('Mismatch between number of word groups and labels')

    all_tokens = {}
    for w, indices in enumerate(word_token_indices):
        if not indices:
            raise ValueError(f'Empty token group at index {w}')
        for t in indices:
            if t < 0 or t >= token_count:
                raise ValueError(f'Token index {t} out of range [0, {token_count-1}]')
            if t in all_tokens:
                raise ValueError(f'Duplicate token index {t}')
            all_tokens[t] = w

    if len(all_tokens) != token_count:
        raise ValueError(f'Not all tokens covered. Got {len(all_tokens)}, expected {token_count}')

    token_labels = [0] * token_count
    for w, indices in enumerate(word_token_indices):
        label = word_labels[w]
        for t in indices:
            token_labels[t] = label

    kept_indices = [i for i, lbl in enumerate(token_labels) if lbl == 1]

    return {'kept_indices': kept_indices, 'token_labels': token_labels}"}
